/**
 * The full Google Fonts catalogue (generated by `npm run fonts:generate` from
 * the `google-font-metadata` package). Ordered by popularity on Google Fonts.
 * Each entry is "Family|category|mask" — see scripts/fonts/generate-google-fonts.ts.
 */
import RAW from "./google-fonts.json"

export type FontCategory = "sans" | "serif" | "display" | "handwriting" | "mono"

export interface GoogleFont {
  family: string
  category: FontCategory
  /** Available static weights, ascending (100…900). */
  weights: number[]
  italic: boolean
}

const CATEGORY: Record<string, FontCategory> = { s: "sans", f: "serif", d: "display", h: "handwriting", m: "mono" }

export const FONT_CATEGORY_LABELS: Record<FontCategory, string> = {
  sans: "Sans serif",
  serif: "Serif",
  display: "Display",
  handwriting: "Handwriting",
  mono: "Monospace",
}

function parse(entry: string): GoogleFont {
  const [family, c, m] = entry.split("|")
  const mask = parseInt(m, 36)
  const weights: number[] = []
  for (let i = 0; i < 9; i++) if (mask & (1 << i)) weights.push((i + 1) * 100)
  return { family, category: CATEGORY[c] ?? "sans", weights, italic: !!(mask & (1 << 9)) }
}

export const GOOGLE_FONTS: readonly GoogleFont[] = (RAW as string[]).map(parse)

const BY_NAME = new Map(GOOGLE_FONTS.map((f) => [f.family.toLowerCase(), f]))

export function findGoogleFont(family: string): GoogleFont | undefined {
  return BY_NAME.get(family.trim().toLowerCase())
}

/** Canonical casing for a catalogue family ("funnel display" → "Funnel Display"). */
export function canonicalFontName(family: string) {
  return findGoogleFont(family)?.family ?? family
}

const UI_WEIGHTS = [400, 500, 600, 700]

/**
 * The `:wght@…` part of a Google Fonts CSS2 URL. Google rejects the whole
 * request when any listed weight does not exist, so only weights the family
 * actually ships are requested. Unknown families load their default style.
 */
export function googleWeightSpec(family: string): string {
  const font = findGoogleFont(family)
  if (!font) return ""
  const wanted = font.weights.filter((w) => UI_WEIGHTS.includes(w))
  if (wanted.length === 1 && wanted[0] === 400) return ""
  if (wanted.length > 0) return `:wght@${wanted.join(";")}`
  // Families without any 400–700 cut (e.g. a light-only display face): take the closest ones.
  const nearest = [...font.weights].sort((a, b) => Math.abs(a - 500) - Math.abs(b - 500)).slice(0, 2).sort((a, b) => a - b)
  return `:wght@${nearest.join(";")}`
}

/** Case-insensitive search: prefix matches first, then word-start, then substring; popularity order within each. */
export function searchGoogleFonts(query: string, category: FontCategory | "all" = "all"): GoogleFont[] {
  const q = query.trim().toLowerCase().replace(/\s+/g, " ")
  const pool = category === "all" ? GOOGLE_FONTS : GOOGLE_FONTS.filter((f) => f.category === category)
  if (!q) return [...pool]
  const prefix: GoogleFont[] = []
  const word: GoogleFont[] = []
  const inner: GoogleFont[] = []
  for (const f of pool) {
    const name = f.family.toLowerCase()
    if (name.startsWith(q)) prefix.push(f)
    else if (name.includes(` ${q}`)) word.push(f)
    else if (name.includes(q) || name.replace(/ /g, "").includes(q.replace(/ /g, ""))) inner.push(f)
  }
  return [...prefix, ...word, ...inner]
}
